"""CSI sources: every transport that can hand the pipeline a stream of CsiFrames.

The rest of the pipeline is source-agnostic, so a source only has to yield CsiFrames:
  * SyntheticSource - an in-memory frame list, generated by the fixtures for dev and CI.
  * RecordingSource - replays a directory written by `save_recording`.
  * UdpSource - the batched-UDP backhaul the ESP32 mesh sends on.
  * UdpLinkCapture - one operator-prompted capture of every mesh link, for the collect scripts.
  * UdpTimedLinkCapture - every mesh link for a fixed time, for camera-labelled collection.
  * SerialReader - esp-csi over USB serial, one ESP per node; the bring-up path for one or two
    nodes before the UDP mesh exists. Needs `pyserial`.
  * NexmonSource - 5 GHz CSI from a Raspberry Pi running nexmon_csi. Needs `csiread`.
"""

import warnings

from wavetrace.adapters.source.link_capture import UdpLinkCapture, UdpTimedLinkCapture, detect_node_ids
from wavetrace.adapters.source.nexmon import NexmonSource, NexmonSourceOptions
from wavetrace.adapters.source.options import SourceOptions
from wavetrace.adapters.source.recording import RecordingSource, load_recording, save_recording
from wavetrace.adapters.source.serial_reader import SerialReader, SerialSourceOptions
from wavetrace.adapters.source.synthetic import SyntheticSource, build_synthetic_source
from wavetrace.adapters.source.udp import UdpLinkBatchReceiver, UdpSource, UdpSourceOptions, bind_udp_socket
from wavetrace.adapters.source.wire_format import (ESP_CSI_COLUMNS, parse_batch, parse_batch_by_link,
                                                   parse_csi_line, short_mac)
from wavetrace.application.ports import CsiSource

__all__ = [
    "ESP_CSI_COLUMNS", "parse_csi_line", "parse_batch", "parse_batch_by_link", "short_mac",
    "bind_udp_socket", "SourceOptions", "SyntheticSource", "RecordingSource", "UdpSourceOptions",
    "UdpSource", "UdpLinkBatchReceiver", "UdpLinkCapture", "UdpTimedLinkCapture", "detect_node_ids",
    "SerialSourceOptions", "SerialReader", "NexmonSourceOptions", "NexmonSource",
    "save_recording", "load_recording", "parse_time_spans", "build_csi_source", "build_synthetic_source",
]


def parse_time_spans(spec: str) -> list[tuple[float, float]]:
    """'a:b,c:d' -> [(a,b),(c,d)]; '' -> []."""
    if not spec:
        return []
    return [tuple(float(bound_s) for bound_s in part.split(":")) for part in spec.split(",")]


def build_csi_source(options) -> CsiSource:
    """Build a CsiSource from a small options bag: `options.recording` (replay a saved directory) or
    `options.synthetic` (generate frames in-process via `wavetrace.synthetic`, from
    `.antennas`/`.subcarriers`/`.fs`/`.duration`/`.presence`/`.weapon`/`.weapon_depth`/`.seed`)."""
    if options.recording:
        return RecordingSource(options.recording)
    if options.synthetic:
        weapon_spans = parse_time_spans(options.weapon)
        if weapon_spans and options.weapon_depth <= 0.0:
            # depth 0 injects no signal, so the weapon windows would all be one class
            warnings.warn("synthetic --weapon spans set but --weapon-depth is 0: weapon windows will "
                          "carry no signature (pass --weapon-depth > 0)", stacklevel=2)
        return build_synthetic_source(
            num_antennas=options.antennas, num_subcarriers=options.subcarriers, sample_rate_hz=options.fs,
            duration_s=options.duration, presence_spans=parse_time_spans(options.presence),
            weapon_spans=weapon_spans, weapon_signature_depth=options.weapon_depth, seed=options.seed)
    raise SystemExit("a source is required: --recording DIR or --synthetic")
